//! Script de build Tauri : ressources Windows (icône, version), contexte, et — surtout — la
//! liste des commandes IPC de l'application.
//!
//! L'UI n'est pas servie par Tauri mais par le serveur Corde embarqué
//! (`http://127.0.0.1:<port>`), donc depuis une origine « distante » du point de vue de
//! Tauri. Une origine distante n'a accès à AUCUNE commande tant qu'une capacité ne la lui
//! donne pas explicitement : déclarer les commandes ici génère les permissions
//! `allow-<commande>` (dans `permissions/autogenerated/`, ignoré par git) que
//! `capabilities/*.json` référencent.

/// Commandes exposées par `src/commands.rs`. Ajouter une commande = l'ajouter ici, dans
/// `tauri::generate_handler!` (main.rs) et dans la capacité qui doit y avoir accès.
const COMMANDS: &[&str] = &[
    // Contrat avec l'UI web (packages/ui) — ne pas renommer sans la prévenir.
    "get_autostart",
    "set_autostart",
    "restart_app",
    "app_version",
    "update_status",
    "check_update",
    "install_update",
    "open_releases_page",
    "get_update_auto_check",
    "set_update_auto_check",
    // Page locale de démarrage / d'erreur uniquement.
    "boot_status",
];

fn main() {
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS));
    if let Err(error) = tauri_build::try_build(attributes) {
        panic!("tauri-build : {error:#}");
    }
}
